// build.js — runs on Netlify before publishing.
// Writes js/config.js from the SUPABASE_URL and SUPABASE_ANON_KEY environment variables.
const fs = require("fs");

const url = process.env.SUPABASE_URL;
const key = process.env.SUPABASE_ANON_KEY;

if (!url || !key) {
  if (process.env.NETLIFY) {
    console.error("ERROR: set SUPABASE_URL and SUPABASE_ANON_KEY in Netlify (Site settings -> Environment variables).");
    process.exit(1);
  }
  console.warn("SUPABASE_URL / SUPABASE_ANON_KEY not set — leaving js/config.js unchanged.");
  process.exit(0);
}

const content =
  "// Generated by build.js — do not edit.\n" +
  "window.FOCUSLAB_CONFIG = " +
  JSON.stringify({ SUPABASE_URL: url, SUPABASE_ANON_KEY: key }, null, 2) +
  ";\n";

fs.writeFileSync("js/config.js", content);
console.log("js/config.js written from environment variables.");
